15	export const oncallCommand: SlashCommand = {
16	  name: 'oncall',
17	  description: 'Oncall related commands',
18	  kind: CommandKind.BUILT_IN,
19	  autoExecute: false,
20	  subCommands: [
21	    {
22	      name: 'dedup',
23	      description: 'Triage issues labeled as status/possible-duplicate',
24	      kind: CommandKind.BUILT_IN,
25	      autoExecute: true,
26	      action: async (context, args): Promise<OpenCustomDialogActionReturn> => {
27	        const { config } = context.services;
28	        if (!config) {
29	          throw new Error('Config not available');
30	        }
31	
32	        let limit = 50;
33	        if (args && args.trim().length > 0) {
34	          const argArray = args.trim().split(/\s+/);
35	          const parsedLimit = parseInt(argArray[0], 10);
36	          if (!isNaN(parsedLimit) && parsedLimit > 0) {
37	            limit = parsedLimit;
38	          }
39	        }
40	
41	        return {
42	          type: 'custom_dialog',
43	          component: (
44	            <TriageDuplicates
45	              config={config}
46	              initialLimit={limit}
47	              onExit={() => context.ui.removeComponent()}
48	            />
49	          ),
50	        };
51	      },
52	    },
53	    {
54	      name: 'audit',
55	      description: 'Triage issues labeled as status/need-triage',
56	      kind: CommandKind.BUILT_IN,
57	      autoExecute: true,
58	      action: async (context, args): Promise<OpenCustomDialogActionReturn> => {
59	        const { config } = context.services;
60	        if (!config) {
61	          throw new Error('Config not available');
62	        }
63	
64	        let limit = 100;
65	        let until: string | undefined;
66	
67	        if (args && args.trim().length > 0) {
68	          const argArray = args.trim().split(/\s+/);
69	          for (let i = 0; i < argArray.length; i++) {
70	            const arg = argArray[i];
71	            if (arg === '--until') {
72	              if (i + 1 >= argArray.length) {
73	                throw new Error('Flag --until requires a value (YYYY-MM-DD).');
74	              }
75	              const val = argArray[i + 1];
