import type React from 'react';
import { useMemo, useState } from 'react';
import { Box, Text } from 'ink';
import { theme } from '../semantic-colors.js';
import { useKeypress } from '../hooks/useKeypress.js';

/**
 * A single hook entry to display in the {@link HooksDialog}.
 */
export interface HookEntry {
  config: {
    name?: string;
    command?: string;
    type?: string;
    description?: string;
    timeout?: number;
  };
  source: string;
  eventName: string;
  matcher?: string;
  sequential?: boolean;
  enabled: boolean;
}

interface HooksDialogProps {
  /** The hooks to display. */
  hooks: HookEntry[];
  /** Invoked when the dialog should be dismissed. */
  onClose: () => void;
  /**
   * Maximum number of hooks to render at once. When the number of hooks
   * exceeds this value, the list becomes scrollable.
   */
  maxVisibleHooks?: number;
}

/**
 * Get the display name for a hook, falling back to the command when no
 * friendly name is configured.
 */
function getHookDisplayName(hook: HookEntry): string {
  return hook.config.name || hook.config.command || 'unknown';
}

/**
 * Group an ordered list of hooks by their event name, preserving order.
 */
function groupByEvent(hooks: HookEntry[]): Array<[string, HookEntry[]]> {
  const groups: Array<[string, HookEntry[]]> = [];
  const index = new Map<string, HookEntry[]>();
  for (const hook of hooks) {
    let group = index.get(hook.eventName);
    if (!group) {
      group = [];
      index.set(hook.eventName, group);
      groups.push([hook.eventName, group]);
    }
    group.push(hook);
  }
  return groups;
}

/**
 * An interactive dialog for displaying the configured hooks. It is rendered
 * separately from the message stream and supports scrolling when the number
 * of hooks exceeds {@link HooksDialogProps.maxVisibleHooks}.
 */
export const HooksDialog: React.FC<HooksDialogProps> = ({
  hooks,
  onClose,
  maxVisibleHooks,
}) => {
  const total = hooks.length;

  // The largest valid scroll offset. When scrolling is disabled (no
  // maxVisibleHooks, or all hooks fit) this is 0.
  const maxOffset =
    maxVisibleHooks && total > maxVisibleHooks ? total - maxVisibleHooks : 0;

  const [scrollOffset, setScrollOffset] = useState(0);

  const clampedOffset = Math.min(scrollOffset, maxOffset);

  useKeypress(
    (key) => {
      if (key.name === 'escape') {
        onClose();
        return;
      }
      if (maxOffset === 0) {
        return;
      }
      if (key.name === 'up') {
        setScrollOffset((prev) => Math.max(0, Math.min(prev, maxOffset) - 1));
      } else if (key.name === 'down') {
        setScrollOffset((prev) => Math.min(maxOffset, prev + 1));
      }
    },
    { isActive: true },
  );

  const visibleHooks = useMemo(() => {
    if (!maxVisibleHooks || total <= maxVisibleHooks) {
      return hooks;
    }
    return hooks.slice(clampedOffset, clampedOffset + maxVisibleHooks);
  }, [hooks, total, maxVisibleHooks, clampedOffset]);

  const showScrollUp = clampedOffset > 0;
  const showScrollDown = maxOffset > 0 && clampedOffset < maxOffset;

  const groupedHooks = useMemo(() => groupByEvent(visibleHooks), [visibleHooks]);

  return (
    <Box
      borderStyle="round"
      borderColor={theme.border.default}
      flexDirection="column"
      padding={1}
      width="100%"
    >
      <Text bold>Configured Hooks</Text>

      <Box flexDirection="column" marginTop={1}>
        <Text color={theme.status.warning} bold underline>
          ⚠️ Security Warning:
        </Text>
        <Text color={theme.status.warning}>
          Hooks can execute arbitrary commands on your system. Only use hooks
          from sources you trust. Review hook scripts carefully.
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text>
          Learn more:{' '}
          <Text color={theme.text.link}>https://geminicli.com/docs/hooks</Text>
        </Text>
      </Box>

      {total === 0 ? (
        <Box marginTop={1}>
          <Text>No hooks configured.</Text>
        </Box>
      ) : (
        <Box flexDirection="column" marginTop={1}>
          <Text dimColor>{showScrollUp ? '▲' : ' '}</Text>
          <Box flexDirection="column" paddingLeft={2}>
            {groupedHooks.map(([eventName, eventHooks]) => (
              <Box key={eventName} flexDirection="column" marginBottom={1}>
                <Text color={theme.text.accent} bold>
                  {eventName}:
                </Text>
                <Box flexDirection="column" paddingLeft={2}>
                  {eventHooks.map((hook, index) => {
                    const hookName = getHookDisplayName(hook);
                    const statusColor = hook.enabled
                      ? theme.status.success
                      : theme.text.secondary;
                    const statusText = hook.enabled ? 'enabled' : 'disabled';

                    return (
                      <Box
                        key={`${eventName}-${index}`}
                        flexDirection="column"
                      >
                        <Box>
                          <Text>
                            <Text color={theme.text.accent}>{hookName}</Text>
                            <Text color={statusColor}>
                              {` [${statusText}]`}
                            </Text>
                          </Text>
                        </Box>
                        <Box paddingLeft={2} flexDirection="column">
                          {hook.config.description && (
                            <Text italic>{hook.config.description}</Text>
                          )}
                          <Text dimColor>
                            Source: {hook.source}
                            {hook.config.name &&
                              hook.config.command &&
                              ` | Command: ${hook.config.command}`}
                            {hook.matcher && ` | Matcher: ${hook.matcher}`}
                            {hook.sequential && ` | Sequential`}
                            {hook.config.timeout &&
                              ` | Timeout: ${hook.config.timeout}s`}
                          </Text>
                        </Box>
                      </Box>
                    );
                  })}
                </Box>
              </Box>
            ))}
          </Box>
          <Text dimColor>{showScrollDown ? '▼' : ' '}</Text>
        </Box>
      )}

      <Box marginTop={1}>
        <Text dimColor>
          Tip: Use <Text bold>/hooks enable {'<hook-name>'}</Text> or{' '}
          <Text bold>/hooks disable {'<hook-name>'}</Text> to toggle individual
          hooks. Use <Text bold>/hooks enable-all</Text> or{' '}
          <Text bold>/hooks disable-all</Text> to toggle all hooks at once.
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text color={theme.text.secondary}>(Press Esc to close)</Text>
      </Box>
    </Box>
  );
};
