import { HooksDialog, type HookEntry } from './HooksDialog.js';

function mk(name: string, eventName: string, enabled: boolean): HookEntry {
  return {
    config: { command: name, type: 'command', timeout: 30 },
    source: 'project',
    eventName,
    enabled,
  };
