describe('HooksDialog tmp', () => {
  it('groups by event and shows status + tips', async () => {
    const hooks = [
      mk('a', 'BeforeTool', true),
      mk('b', 'AfterTool', false),
    ];
    const { lastFrame } = renderWithProviders(
      <HooksDialog hooks={hooks} onClose={vi.fn()} />,
    );
    await new Promise((r) => setTimeout(r, 20));
    const frame = lastFrame();
    expect(frame).toContain('BeforeTool');
    expect(frame).toContain('AfterTool');
    expect(frame).toContain('[enabled]');
    expect(frame).toContain('[disabled]');
    expect(frame).toContain('Security Warning');
    expect(frame).toContain('Source: project');
    expect(frame).toContain('Tip:');
  });

  it('shows scroll indicators when exceeding maxVisibleHooks', async () => {
    const hooks = [
      mk('a', 'E1', true),
      mk('b', 'E2', true),
      mk('c', 'E3', true),
      mk('d', 'E4', true),
    ];
    const { lastFrame } = renderWithProviders(
      <HooksDialog hooks={hooks} onClose={vi.fn()} maxVisibleHooks={2} />,
    );
    await new Promise((r) => setTimeout(r, 20));
    const frame = lastFrame();
